export function getFluxo(tipoTrabalho: string): ConfiguracaoFluxo | null {
  return FLUXOS[tipoTrabalho] ?? null
}

export function getFase(tipoTrabalho: string, chaveSecao: string) {
  return FLUXOS[tipoTrabalho]?.fases.find(f => f.chave_secao === chaveSecao) ?? null
}
